(root/'05_제작기록'/'국장보고_구성데이터.json').write_text(json.dumps({'sources':S,'slides':slides},ensure_ascii=False,indent=2))
def md_for(ss,title):
 out=[f'# {title}','', '2026.09.07 회의 반영 작성안 · 보고 본문 및 발표 설명','']
 for s in ss:
  idx=slides.index(s)+1
  out += [f'## {idx:02d}. {s["title"]}', '', s['lead'], '']
  for h,t in s['blocks']:out += [f'### {h}', '',t,'']
  out += ['### 발표 설명', '',s['notes'],'']
  if s['refs']:out += ['출처: '+' / '.join(f'[{k} {S[k][0]}]({S[k][1]})' for k in s['refs']), '']
  else: out += ['작성 근거: 제공된 기존 문서, 2026.09.07 내부회의, 조사 방법표를 바탕으로 재작성.', '']
 return '\n'.join(out)
(root/'04_편집원고'/'10_국장보고_통합전체원고.md').write_text(md_for(slides,'인천 창의디자인 사회실험 | 국장보고 전체 원고'))
for i,site in enumerate(dict.fromkeys(s['site'] for s in slides if s['site'])):
 ss=[s for s in slides if s['site']==site]
 (root/'04_편집원고'/f'11_{site}_국장보고.md').write_text(md_for(ss,site.split('_',1)[1]+' | 국장보고 전체 원고'))
print('slides',len(slides),'report_chars',len(md_for(slides,'')))
